function surfaceTexture(){if(nativeTexture?.terrainId!==terrain?.id)return null;if($('surfaceStyle').value!=='mixed')return nativeTexture.canvas;if(!nativeTexture.mixed){const c=document.createElement('canvas');c.width=c.height=512;const ctx=c.getContext('2d'),range=elevationRange(terrain);ctx.drawImage(nativeTexture.canvas,0,0);ctx.globalAlpha=.45;for(let y=0;y<terrain.height;y++)for(let x=0;x<terrain.width;x++){const z=terrain.elevations[y*terrain.width+x];if(z===null)continue;ctx.fillStyle=`rgb(${elevationRGB(z,range.min,range.max).join(',')})`;ctx.fillRect((x-.5)*512/(terrain.width-1),(y-.5)*512/(terrain.height-1),512/(terrain.width-1)+1,512/(terrain.height-1)+1);}nativeTexture.mixed=c;}return nativeTexture.mixed;}
