function savePoints(){try{const all=JSON.parse(localStorage.getItem(STORAGE)||'{}');all[bodyKey]=points;localStorage.setItem(STORAGE,JSON.stringify(all));}catch{$('waypointState').textContent='Destinos disponibles en esta sesión; no se pudieron guardar.';}}
