function renderPoints(){const list=$('waypointList');list.replaceChildren();for(const [i,p] of points.entries()){const li=document.createElement('li'),text=document.createElement('span'),remove=document.createElement('button');text.textContent=`${p.name} · ${p.lat.toFixed(4)}, ${p.lon.toFixed(4)}`;remove.textContent='×';remove.setAttribute('aria-label',`Quitar ${p.name}`);remove.onclick=()=>{points.splice(i,1);savePoints();renderPoints();invalidate();};li.append(text,remove);list.append(li);}let n=points.length+1;while(points.some(p=>p.name===`Destino ${n}`))n++;$('waypointName').value=`Destino ${n}`;controls();}
function storePoint(lat,lon){const name=$('waypointName').value.trim();if(!terrain)throw Error('Carga primero una región.');if(!name||name.length>60||points.some(p=>p.name===name))throw Error('Usa un nombre único de 1–60 caracteres.');if(points.length>=19)throw Error('La ruta admite hasta 19 destinos más el vehículo actual.');if(!Number.isFinite(lat)||Math.abs(lat)>90||!Number.isFinite(lon)||Math.abs(lon)>180)throw Error('Coordenadas no válidas.');const grid=gridPosition({lat,lon},terrain);if(!inTerrain(grid,terrain))throw Error('El destino queda fuera de esta región.');points.push({name,lat,lon});savePoints();renderPoints();invalidate('Destino agregado. Calcula la ruta desde el vehículo.');$('waypointState').textContent='Destino guardado para este cuerpo celeste.';}
$('waypointForm').onsubmit=e=>{e.preventDefault();try{storePoint(Number($('waypointLat').value),Number($('waypointLon').value));}catch(error){$('waypointState').textContent=error.message;}};
