 if(pendingMap){const t=pendingMap;pendingMap=null;if(t.body===sample.body&&t.bodyRadius===sample.bodyRadius){useTerrain(t);importedMap=true;$('archiveState').textContent='Mapa guardado con telemetría actual. Revisa que pertenezca a esta instalación y mods de KSP.';}else $('archiveState').textContent='El cuerpo o radio del juego no coincide con el mapa guardado. Carga otro mapa o muestrea.';}
 $('bodyName').textContent=next.body;$('vesselName').textContent=next.vessel;$('vesselCoords').textContent=`${next.latitude.toFixed(5)}°, ${sample.longitude.toFixed(5)}°`;$('vesselMotion').textContent=`${next.heading.toFixed(0)}° / ${next.speed.toFixed(1)} m/s`;$('vesselAltitude').textContent=`${next.surfaceAltitude.toFixed(1)} m`;$('positionReadout').textContent=`${mode==='offline'?(rehearsal?'EXPLORADOR VIRTUAL':'Salida manual'):mode==='demo'?'DEMO':'KSP'} · ${next.body} · ${next.latitude.toFixed(5)}°, ${sample.longitude.toFixed(5)}° · rumbo ${next.heading.toFixed(0)}°`;
 if(compatible()){const p=vesselGrid(),context=surfaceContext(terrain,sample,p);$('vehicleContext').textContent=mode==='offline'?'Preparación sin juego: salida manual.':context.message;if(inTerrain(p,terrain)){const last=track.at(-1);if(!last||Math.hypot(last.x-p.x,last.y-p.y)*terrain.cellMeters>1){track.push(p);if(track.length>600)track.shift();}}followRoute();}
