$('sampleTerrain').onclick=async()=>{if(mode!=='live'||!fresh)return;try{invalidate('Muestreando una región nueva; guía en pausa.');const token=++jobToken,context=generation;const accepted=await jsonRequest('/api/ksp/terrain',{body:{size:Number($('regionSize').value),cellMeters:Number($('cellSize').value)}});if(context!==generation||token!==jobToken||mode!=='live'){fetch('/api/ksp/terrain/cancel',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({jobId:accepted.id}),keepalive:true}).catch(()=>{});return;}ownedJob=accepted.id;terrain=null;jobTimer=setTimeout(()=>pollJob(token),200);$('terrainState').textContent='Muestreo solicitado. Puedes cancelarlo sin controlar el juego.';controls();draw();}catch(error){$('terrainState').textContent=error.message;}};
$('recenterTerrain').onclick=()=>{if(mode!=='live'||!fresh||jobTimer)return;if(mission){points=remainingStops(mission,terrain,progress).map(({name,lat,lon})=>({name,lat,lon}));savePoints();renderPoints();}recenterPending=true;record('region-request','Nueva región con destinos pendientes conservados');$('sampleTerrain').click();};
