$('loadDemo').onclick=async()=>{stopSource();mode='demo';beginSession('demo');const token=generation;try{const data=await jsonRequest('/api/ksp/demo/terrain');if(token!==generation)return;const t=data.terrain;bodyKey=`${t.body}|${t.bodyRadius}`;loadPoints();sample={latitude:t.center.lat,longitude:t.center.lon,heading:0,surfaceAltitude:1,speed:0,bodyRadius:t.bodyRadius,body:t.body,vessel:'Rover de demostración',vesselId:'demo',receivedAt:Date.now()/1000};fresh=true;useTerrain(t);acceptSample(sample);$('demoControls').hidden=false;$('connectionState').textContent='DEMO SINTÉTICA: terreno y vehículo de prueba, sin una partida conectada.';}catch(error){$('connectionState').textContent=error.message;}};
