let drag=null,moved=false;canvas.onpointerdown=e=>{if(e.button!==0)return;canvas.focus();drag={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY};moved=false;canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(terrain&&!is3d){const box=canvas.getBoundingClientRect(),x=Math.round((e.clientX-box.left-view.x)/view.scale),y=Math.round((e.clientY-box.top-view.y)/view.scale);if(inTerrain({x,y},terrain)){const reach=reachability(),i=y*terrain.width+x,z=terrain.elevations[i],slope=reach?.slopes[i]??slopeAt(terrain,x,y);$('cellInfo').textContent=`Celda ${x},${y} · altura ${z===null?'sin datos':z.toFixed(1)+' m'} · pendiente ${Number.isFinite(slope)?slope.toFixed(1)+'°':'sin datos'} · ${reach?.reachable[i]?'alcanzable':reach?.pass[i]?'sin conexión al vehículo':'bloqueada'}`;}}if(!drag)return;if(Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>5)moved=true;$ ('followVehicle').checked=false;pan.x+=e.clientX-drag.x;pan.y+=e.clientY-drag.y;drag.x=e.clientX;drag.y=e.clientY;draw();};canvas.onpointerup=canvas.onpointercancel=()=>drag=null;
canvas.onclick=e=>{if(moved||!terrain)return;const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left-view.x)/view.scale,y=(e.clientY-r.top-view.y)/view.scale;try{if(!inTerrain({x,y},terrain))throw Error('Pulsa dentro del terreno muestreado.');const geo=geoFromGrid(terrain,x,y);$('waypointLat').value=geo.lat;$('waypointLon').value=geo.lon;storePoint(geo.lat,geo.lon);}catch(error){$('waypointState').textContent=error.message;}};
canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.5,Math.min(10,zoom*Math.exp(-e.deltaY*.0015)));draw();},{passive:false});canvas.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-','0'].includes(e.key))return;e.preventDefault();$('followVehicle').checked=false;if(e.key==='0'){zoom=1;pan={x:0,y:0};}else{pan.x+=e.key==='ArrowLeft'?30:e.key==='ArrowRight'?-30:0;pan.y+=e.key==='ArrowUp'?30:e.key==='ArrowDown'?-30:0;zoom=Math.max(.5,Math.min(10,zoom*(e.key==='+'?1.25:e.key==='-'?.8:1)));}draw();};
$('centerMap').onclick=()=>{zoom=1;pan={x:0,y:0};$('followVehicle').checked=false;relief?.reset();draw();};
$('map2d').onclick=()=>{is3d=false;canvas.hidden=false;$('native3d').hidden=true;relief?.setActive(false);$('map2d').setAttribute('aria-pressed','true');$('map3dButton').setAttribute('aria-pressed','false');draw();};
$('map3dButton').onclick=async()=>{if(!terrain)return;try{if(!relief){const {createKspRelief}=await import('./ksp-view3d.js');relief=createKspRelief($('native3d'),{onMove:p=>{if(mode!=='offline'||!compatible()||!inTerrain(p,terrain)){say('Movimiento virtual solo disponible sin juego y dentro de la región.');return;}rehearsal=true;const g=geoFromGrid(terrain,p.x,p.y);acceptSample({...sample,latitude:g.lat,longitude:g.lon,speed:0,receivedAt:Date.now()/1000});$('rehearsalStatus').textContent='Explorador virtual · WASD. No mueve el rover de KSP.';},onView:view=>{$('kspCompass').textContent=`↑ N · ${view.bearing.toFixed(0).padStart(3,'0')}°`;$('followVehicle').checked=view.following;},onPick:p=>{const geo=geoFromGrid(terrain,p.x,p.y);$('waypointLat').value=geo.lat;$('waypointLon').value=geo.lon;$('cellInfo').textContent=`3D: ${p.elevation.toFixed(1)} m · ${geo.lat.toFixed(5)}°, ${geo.lon.toFixed(5)}°. Pulsa Agregar coordenadas para marcarlo.`;}});}is3d=true;canvas.hidden=true;$('native3d').hidden=false;$('map2d').setAttribute('aria-pressed','false');$('map3dButton').setAttribute('aria-pressed','true');draw();relief.setActive(true);}catch(error){say(`No se pudo abrir WebGL: ${error.message}. Puedes seguir usando el mapa 2D.`);$('map2d').click();}};
new ResizeObserver(draw).observe(canvas);
function syncVisibility(){if(hiddenView()){relief?.setActive(false);stopNativeXR();clearInterval(weatherTimer);weatherTimer=null;$('cycleDunaWeather').setAttribute('aria-pressed','false');$('cycleDunaWeather').textContent='▶ Ciclo simulado cada 20 s (opcional)';viewPaused=true;telemetryEpoch++;arrival.stopSince=null;record('visibility','hidden: guía pausada');stopDemo();clearTimeout(pollTimer);telemetryRequest?.abort();if(planRequest)say('Cálculo pausado al ocultar la vista. Pulsa calcular al volver.');planVersion++;planRequest?.abort();planRequest=null;navigation.pause();fresh=false;$('navigationBanner').hidden=true;$('driverAdvice').hidden=true;$('connectionState').textContent='Vista oculta: guía pausada. Se comprobará la conexión al volver.';journal.flush();flushEvents();controls();}else{if(is3d&&!atlas?.active)relief?.setActive(true);viewPaused=false;record('visibility','visible: comprobando conexión');if(mode==='live'){const resume=()=>{if(!telemetryRequest&&!hiddenView()){poll();return;}if(!hiddenView())setTimeout(resume,50);};resume();}else if(mode==='demo'||mode==='offline'){fresh=true;$('connectionState').textContent=mode==='offline'?'MAPA IMPORTADO · PREPARACIÓN SIN JUEGO. Salida manual, sin telemetría.':'DEMO SINTÉTICA · sin conexión al juego.';controls();draw();}}}
document.addEventListener('visibilitychange',syncVisibility);
window.addEventListener('message',event=>{if(embedded&&event.source===parent&&event.origin===location.origin&&event.data?.type==='ksp-workspace-visibility'){embeddedHidden=!event.data.visible;syncVisibility();}});
window.addEventListener('pagehide',()=>{if(mode==='live'&&journal.current?.performance)record('performance-snapshot',JSON.stringify(timingSnapshot(journal.current.performance)));record('pagehide','Cierre de vista');journal.flush();stopSource();});
$('downloadSession').onclick=()=>{if(!journal.current)return;journal.flush();downloadEvidence(journal.current,`ksp-map-session-${journal.current.id}.json`);};
function downloadEvidence(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('downloadConnector').onclick=()=>{if(!diskAvailable)return;const a=document.createElement('a');a.href='/api/ksp/session/export';a.download='';a.click();};
for(const [id,action] of [['cloudPause','pause'],['cloudResume','resume'],['cloudRetry','retry'],['cloudRevoke','revoke']])$(id).onclick=async()=>{try{const result=await jsonRequest('/api/ksp/cloud/control',{body:{action}});if(action==='revoke'){showConsent({uploadConsent:result.consent});for(const id of ['cloudPause','cloudResume','cloudRetry'])$(id).disabled=true;$('cloudStatus').textContent='Permiso retirado. Reinicia el conector para mostrar el aviso si quieres volver a compartir. Lo ya enviado se conserva.';return;}$('cloudStatus').textContent=action==='pause'?'Pausa solicitada. Una transferencia ya iniciada puede terminar.':'Envío solicitado; comprueba el estado del conector.';}catch(error){$('cloudStatus').textContent=error.message;}};
let storedSessions=[];
$('refreshSessions').onclick=async()=>{try{await journal.flush();storedSessions=await journal.list();$('savedSessions').replaceChildren(new Option('Selecciona una sesión',''),...storedSessions.map(s=>new Option(`${s.startedAt} · ${s.mode} · ${s.samples.length} muestras`,s.id)));$('downloadSaved').disabled=true;}catch{$('sessionStatus').textContent='No se pudieron leer sesiones anteriores. Puedes descargar la sesión actual.';}};
$('savedSessions').onchange=()=>{$('downloadSaved').disabled=!$('savedSessions').value;};
$('downloadSaved').onclick=()=>{const value=storedSessions.find(s=>s.id===$('savedSessions').value);if(value)downloadEvidence(value,`ksp-map-session-${value.id}.json`);};
controls();draw();

$('native3d').addEventListener('webglcontextlost',event=>{event.preventDefault();$('map2d').click();say('Se perdió el contexto WebGL. Puedes continuar en 2D.');});

function selectedObjective(){return catalogPoints.find(p=>p.name===$('dunaObjective').value);}
function renderObjectives(){const previous=$('dunaObjective').value;$('dunaObjective').replaceChildren(new Option('Selecciona un objetivo',''),...catalogPoints.filter(p=>$('objectiveFilter').value==='all'||p.kind===$('objectiveFilter').value).map(p=>new Option(p.name,p.name)));if([...$('dunaObjective').options].some(o=>o.value===previous))$('dunaObjective').value=previous;$('dunaObjective').onchange();}
$('objectiveFilter').onchange=renderObjectives;
$('dunaObjective').onchange=()=>{const p=selectedObjective();$('objectiveDetails').textContent=p?`${p.description} Coordenadas: ${p.lat.toFixed(5)}°, ${p.lon.toFixed(5)}°.`:'Objetivos de pruebas reales del equipo, separados de los datos científicos de Marte.';$('objectiveSource').hidden=!p;if(p)$('objectiveSource').href=p.source;$('viewObjective').disabled=!p;$('addObjective').disabled=!p;};
$('showDunaObjectives').onchange=draw;
$('addObjective').onclick=()=>{const p=selectedObjective();if(!p)return;try{if(terrain?.body!=='Duna')throw Error('Este objetivo pertenece a Duna.');$('waypointName').value=p.name;storePoint(p.lat,p.lon);}catch(e){$('waypointState').textContent=e.message+' Abre primero la región del objetivo si queda fuera.';}};
$('viewObjective').onclick=async()=>{const p=selectedObjective();if(!p)return;if(mode==='live'){$('objectiveDetails').textContent='Para cambiar la región con el juego conectado, usa el muestreo local. Puedes consultar este punto en el mapa completo.';return;}try{await atlas.openAt(p);$('waypointName').value=p.name;$('waypointLat').value=p.lat;$('waypointLon').value=p.lon;}catch(e){$('objectiveDetails').textContent=e.message;}};
fetch('/public/data/duna-objectives.json').then(r=>r.json()).then(data=>{catalogPoints=data.points;renderObjectives();draw();}).catch(()=>{$('objectiveDetails').textContent='Catálogo de objetivos no disponible; puedes añadir destinos propios.';});
$('dunaWeather').onchange=()=>{const state=weather();if(mission?.environment?.scenario===state.scenario&&mission.environment.wind?.fromDegrees===state.wind.fromDegrees){draw();return;}stopRehearsal();reachCache=null;$('dunaDustVeil').style.opacity=state.opacity;$('windStreaks').hidden=!state.wind.speedMS;$('windStreaks').style.setProperty('--wind-angle',`${state.wind.fromDegrees+180}deg`);$('windStreaks').style.animationDuration=state.scenario==='storm'?'2s':'5s';$('windReadout').textContent=`VIENTO SIMULADO · ${state.wind.speedMS} m/s · ráfagas ${state.wind.gustMS} m/s · desde ${state.wind.fromDegrees}° · visibilidad ${state.visibilityMeters} m`;$('dunaWeatherStatus').textContent=`${$('dunaWeather').selectedOptions[0].text} · SIMULADO. No cambia el clima de KSP. ${state.zones.length?'Zona naranja restringida para el cálculo de rutas.':''}`;if($('shareGameWeather').checked)shareWeather();record('training-weather',JSON.stringify({scenario:state.scenario,wind:state.wind,visibilityMeters:state.visibilityMeters}));navigation.announce(`Escenario simulado: ${$('dunaWeather').selectedOptions[0].text}. Viento ${state.wind.speedMS} metros por segundo, ráfagas ${state.wind.gustMS}.`);if(mission&&fresh){planVersion++;planRequest?.abort();planRequest=null;planNative('weather');}else draw();};
async function shareWeather(){try{const state=weather();await jsonRequest('/api/ksp/weather',{body:{enabled:$('shareGameWeather').checked,scenario:state.scenario,windDirection:state.wind.fromDegrees}});$('gameWeatherStatus').textContent='Escenario disponible en el conector. El mod requiere activar entrenamiento y Seguir mapa local dentro de KSP.';}catch{$('gameWeatherStatus').textContent='No se pudo compartir: abre localhost:7173 con el conector actualizado. El mapa conserva la simulación.';}}
$('shareGameWeather').onchange=shareWeather;
setInterval(()=>{if($('shareGameWeather').checked&&!hiddenView())shareWeather();},5000);
$('windDirection').onchange=()=>{const v=Number($('windDirection').value);if(!Number.isFinite(v)||v<0||v>=360){$('windDirection').value='90';$('gameWeatherStatus').textContent='Usa una dirección entre 0 y 359 grados.';}$('dunaWeather').onchange();};
$('cycleDunaWeather').onclick=()=>{if(weatherTimer){clearInterval(weatherTimer);weatherTimer=null;$('cycleDunaWeather').setAttribute('aria-pressed','false');$('cycleDunaWeather').textContent='▶ Ciclo simulado cada 20 s (opcional)';record('weather-cycle','disabled');return;}$('cycleDunaWeather').setAttribute('aria-pressed','true');$('cycleDunaWeather').textContent='■ Detener ciclo simulado (cambia cada 20 s)';record('weather-cycle','enabled: clear → wind → dust → storm cada 20 s');weatherTimer=setInterval(()=>{if(hiddenView())return;const values=['clear','wind','dust','storm'];$('dunaWeather').value=values[(values.indexOf($('dunaWeather').value)+1)%3];$('dunaWeather').onchange();},20000);};
function rehearseAt(value){if(mode!=='offline'||!mission||suspended)return;rehearsal=true;const g=positionAtProgress(mission.gridPath,terrain,value),p=geoFromGrid(terrain,g.x,g.y);$('rehearsalProgress').value=Math.round(value*1000);$('rehearsalStatus').textContent=`ENSAYO VIRTUAL · ${Math.round(value*100)}% · no mueve el rover de KSP.`;acceptSample({...sample,latitude:p.lat,longitude:p.lon,speed:value>=1?0:Number($('roverSpeed').value)*weather().speedFactor,receivedAt:Date.now()/1000});progress=value;navigation.update(value,value<1);}
$('rehearsalProgress').oninput=()=>{stopRehearsal();rehearseAt(Number($('rehearsalProgress').value)/1000);};
$('rehearseRoute').onclick=()=>{if(rehearsalTimer){stopRehearsal();navigation.pause();return;}if(mode!=='offline'||!mission||suspended)return;rehearsal=true;if(progress>=1)progress=0;$('rehearseRoute').setAttribute('aria-pressed','true');let last=performance.now();rehearsalTimer=setInterval(()=>{if(hiddenView()){stopRehearsal();return;}const now=performance.now(),dt=Math.min(1,(now-last)/1000);last=now;const distance=mission?.metrics.distance;if(!distance){stopRehearsal();return;}rehearseAt(Math.min(1,progress+dt*Number($('roverSpeed').value)*weather().speedFactor*Number($('rehearsalSpeed').value)/distance));if(progress>=1)stopRehearsal();},100);};
for(const [id,mode] of [['cameraAerial','aerial'],['cameraFlyover','flyover'],['cameraFollow','follow'],['cameraSurface','surface']])$(id).onclick=async()=>{atlas?.hide();if(!terrain)return;await $('map3dButton').onclick();relief?.setMode(mode);};
$('dunaOrbit').onclick=async()=>{if(!terrain)return;atlas?.hide();await $('map3dButton').onclick();const running=relief?.toggleOrbit();$('dunaOrbit').setAttribute('aria-pressed',String(!!running));};
atlas=createDunaAtlas({getState:()=>({lightweight:$('lightweightMode').checked,terrain,sample,points,mission,catalogPoints:$('showDunaObjectives').checked?catalogPoints:[]}),openRegion:async raw=>{await openArchive(raw);const meta=await textureMetadata('/public/imagery/ksp-duna-travesia-metadata.json');await applyImage(await loadImage(meta.image),meta);await $('map3dButton').onclick();},onVisibility:visible=>{if(visible){stopRehearsal();navigation.pause();relief?.setActive(false);}else if(is3d)relief?.setActive(true);}});
if(new URLSearchParams(location.search).get('view')==='atlas')atlas.show('2d').catch(()=>{});

function stopNativeXR(){nativeARGeneration++;const current=nativeXR;nativeXR=null;current?.end().catch(()=>{});document.body.classList.remove('native-xr');$('nativeXR').hidden=true;$('stopNativeAR').hidden=true;}
$('nativeHud').onclick=()=>{atlas?.hide();document.body.classList.add('native-hud');$('exitNativeHud').hidden=false;};
$('exitNativeHud').onclick=()=>{document.body.classList.remove('native-hud');$('exitNativeHud').hidden=true;};
$('stopNativeAR').onclick=stopNativeXR;
$('nativeAR').onclick=async()=>{if(!terrain)return;const token=++nativeARGeneration,requestedTerrain=terrain;try{if(!navigator.xr||!await navigator.xr.isSessionSupported('immersive-ar'))throw Error('Este dispositivo no ofrece WebXR AR. Puedes seguir con el globo, superficie y HUD.');if(token!==nativeARGeneration||requestedTerrain!==terrain||hiddenView())return;atlas?.hide();let texture=nativeTexture?.terrainId===terrain.id?nativeTexture.canvas:null;if(!texture){texture=document.createElement('canvas');texture.width=terrain.width;texture.height=terrain.height;const c=texture.getContext('2d'),range=elevationRange(terrain);terrain.elevations.forEach((z,i)=>{c.fillStyle=z===null?'#293330':`rgb(${elevationRGB(z,range.min,range.max).join(',')})`;c.fillRect(i%terrain.width,Math.floor(i/terrain.width),1,1);});}const current=terrain,{startTabletopAR}=await import('./ar-xr.js');if(token!==nativeARGeneration||current!==terrain||hiddenView())return;const session=await startTabletopAR($('nativeXR'),document.body,current,mission?.gridPath||[],{textureCanvas:texture,size:()=>.6,progress:()=>progress,onStatus:text=>$('nativeARStatus').textContent=text,onEnd:()=>{if(token!==nativeARGeneration)return;nativeXR=null;document.body.classList.remove('native-xr');$('stopNativeAR').hidden=true;}});if(token!==nativeARGeneration||current!==terrain||hiddenView()){await session.end().catch(()=>{});return;}nativeXR=session;document.body.classList.add('native-xr');$('stopNativeAR').hidden=false;}catch(e){stopNativeXR();$('nativeARStatus').textContent=e.message;}};
window.addEventListener('pagehide',()=>{stopNativeXR();clearInterval(weatherTimer);});

function showDiagnostics(info){const computer=info?.computer,s=computer?.sample,flight=info?.flight;const pct=v=>Number.isFinite(v)?`${v.toFixed(0)}%`:'sin dato';const gb=v=>Number.isFinite(v)?`${(v/1024**3).toFixed(1)} GB`:'sin dato';if(s){const age=Math.max(0,Date.now()/1000-s.at);$('computerState').textContent=`${s.os} · CPU ${pct(s.cpuPercent)} · RAM ${pct(s.ramPercent)} (${gb(s.ramUsedBytes)} / ${gb(s.ramTotalBytes)}) · disco libre ${gb(s.diskFreeBytes)} · KSP ${s.kspDetected===true?'detectado · RAM KSP '+gb((s.kspProcesses||[]).reduce((n,p)=>n+(p.rssBytes||0),0)):s.kspDetected===false?'no detectado':'sin comprobación'}${age>15?' · DATOS ANTIGUOS':''}${s.status==='partial'?' · métricas parciales':''}`;}else $('computerState').textContent=computer?.enabled?'Esperando medición del equipo…':'Estadísticas del equipo desactivadas o conector antiguo.';if(flight){const value=(v,unit)=>Number.isFinite(v)?`${v.toFixed(1)} ${unit}`:'sin dato';$('flightState').textContent=`Vuelo: ${flight.situation} · altitud ${value(flight.meanAltitude,'m')} · vertical ${value(flight.verticalSpeed,'m/s')} · horizontal ${value(flight.horizontalSpeed,'m/s')} · apoapsis ${value(flight.apoapsisAltitude,'m')} · periapsis ${value(flight.periapsisAltitude,'m')}`;}else $('flightState').textContent='Datos adicionales de vuelo no disponibles; no se simulan.';const a=info?.analysis;$('healthSummary').textContent=a?`Registro: ${a.telemetrySamples} muestras · PC ${a.diagnosticSamples?.computer||0} · vuelo ${a.diagnosticSamples?.flight||0}. ${a.recommendations?.join(' ')||'Sin avisos por los umbrales actuales; no certifica que toda la sesión sea correcta.'}`:'Sin resumen de diagnóstico del conector.';const perf=a?.browserPerformance?.renderCpu;if(perf)$('healthSummary').textContent+=` Repintado CPU: media ${perf.meanMs.toFixed(1)} ms${Number.isFinite(perf.p95RecentMs)?' · p95 reciente '+perf.p95RecentMs.toFixed(1)+' ms':''} (${perf.count} mediciones; no son FPS).`;}
setInterval(()=>{if(mode==='live'&&!hiddenView()&&journal.current?.performance)record('performance-snapshot',JSON.stringify(timingSnapshot(journal.current.performance)));},30000);

function showConsent(info){const c=info?.uploadConsent;$('uploadConsentStatus').textContent=c?.allowed?`Permiso concedido para esta sesión · destino ${c.project}. ${c.automaticRegistration?'Registro automático de esta instalación; sin correo ni contraseña.':'Usa la sesión de Supabase configurada.'}`:c?.reason==='revoked'?'Permiso retirado: no se inician nuevos envíos. Lo ya enviado no se borra.':'Sin permiso de envío. El mapa y el registro local siguen funcionando. Reinicia el conector para mostrar el aviso.';$('cloudRevoke').disabled=!c?.allowed;}

if(!['localhost','127.0.0.1','[::1]'].includes(location.hostname)){const notice=document.createElement('p');notice.setAttribute('role','note');notice.textContent='Para conectar el juego de tu PC, inicia el conector y abre http://localhost:7173/ksp-map.html. Esta web remota ofrece el mapa y la preparación; no conecta directamente con tu kRPC local.';$('connectGame').insertAdjacentElement('afterend',notice);}
